liskov.setup:
class Rectangle:
    def __init__(self, width, height):
        self.width, self.height = width, height
    def set_width(self, w):
        self.width = w
    def set_height(self, h):
        self.height = h
    def area(self):
        return self.width * self.height

class Square(Rectangle):                 # forces width == height
    def __init__(self, side):
        super().__init__(side, side)
    def set_width(self, w):
        self.width = self.height = w
    def set_height(self, h):
        self.width = self.height = h

def resize(r):
    """A caller written against Rectangle: widen, then set the height."""
    r.set_width(5)
    r.set_height(4)
    return r.area()                       # a rectangle's promise: 5 x 4 = 20

fragileBefore.setup:
class Cart:
    def __init__(self):
        self.items = []
    def add(self, item):
        self.items.append(item)
    def add_all(self, items):
        for item in items:
            self.add(item)

class LoyaltyCart(Cart):                  # inheritance: counts inside add()
    def __init__(self):
        super().__init__()
        self.counted = 0
    def add(self, item):
        self.counted += 1
        super().add(item)

class LoyaltyCounter:                     # composition: holds a cart
    def __init__(self, cart):
        self.cart = cart
        self.counted = 0
    def add(self, item):
        self.counted += 1
        self.cart.add(item)
    def add_all(self, items):
        items = list(items)
        self.counted += len(items)
        self.cart.add_all(items)

